python3 << 'EOF'
import json

# Load the JSON file
with open('/app/resources/treasury_bulletin_1940_03.json', 'r') as f:
    data = json.load(f)

# Print the keys at the top level
print("Top-level keys:", list(data.keys())[:10])

# Navigate to find UK exchange rate section
def find_uk_data(obj, path=""):
    results = []
    if isinstance(obj, dict):
        for k, v in obj.items():
            if 'united' in k.lower() or 'kingdom' in k.lower() or 'britain' in k.lower():
                results.append((path + "." + k if path else k, k, v))
            results.extend(find_uk_data(v, path + "." + k if path else k))
    elif isinstance(obj, list):
        for i, item in enumerate(obj):
            results.extend(find_uk_data(item, f"{path}[{i}]"))
    return results

results = find_uk_data(data)
for r in results[:20]:
    print(r)
